import{_ as s,o as a,c as i,aO as o}from"./chunks/framework.vjUPZZJn.js";const m=JSON.parse('{"title":"VS Code Remote-SSH 卡在\\"正在下载 VS Code 服务器\\"：手动安装","description":"","frontmatter":{"date":"2026-11-16T12:10:00.000Z","title":"VS Code Remote-SSH 卡在\\"正在下载 VS Code 服务器\\"：手动安装","source":[["1-知识/工具/网络代理与远程/VS Code Remote-SSH 手动安装服务器"]],"tags":["工具","问题排查","VSCode","SSH"],"categories":["问题排查"],"permalink":"/pages/68f974"},"headers":[],"relativePath":"问题排查/VS Code Remote-SSH 卡在正在下载服务器：手动安装.md","filePath":"问题排查/VS Code Remote-SSH 卡在正在下载服务器：手动安装.md","lastUpdated":1794797791000}'),t={name:"问题排查/VS Code Remote-SSH 卡在正在下载服务器：手动安装.md"};function r(n,e,d,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="vs-code-remote-ssh-卡在-正在下载-vs-code-服务器-手动安装" tabindex="-1">VS Code Remote-SSH 卡在&quot;正在下载 VS Code 服务器&quot;：手动安装 <a class="header-anchor" href="#vs-code-remote-ssh-卡在-正在下载-vs-code-服务器-手动安装" aria-label="Permalink to &quot;VS Code Remote-SSH 卡在&quot;正在下载 VS Code 服务器&quot;：手动安装&quot;">​</a></h1> <p>用 VS Code 的 Remote-SSH 连接服务器时，如果状态栏长时间停留在「正在下载 VS Code 服务器（Setting up SSH Host xx: Downloading VS Code Server）」，最常见的原因是服务器无法访问外网——VS Code 需要从 update.code.visualstudio.com 下载一个与本地版本匹配的 server 端组件，这个下载是在服务器上执行的，服务器不通外网就永远卡住。解决办法是在本地下载好对应组件手动传上去。本文记录完整步骤与两个关键细节。</p> <h2 id="手动安装步骤" tabindex="-1">手动安装步骤 <a class="header-anchor" href="#手动安装步骤" aria-label="Permalink to &quot;手动安装步骤&quot;">​</a></h2> <h3 id="_1-获取本地-vs-code-的-commit-id" tabindex="-1">1. 获取本地 VS Code 的 commit id <a class="header-anchor" href="#_1-获取本地-vs-code-的-commit-id" aria-label="Permalink to &quot;1. 获取本地 VS Code 的 commit id&quot;">​</a></h3> <p>VS Code 每个版本的 server 组件与 commit 哈希一一对应，所以先要拿到本地客户端的 commit id：</p> <ul><li>菜单 <strong>Help → About</strong>，查看 Commit 行；或</li> <li>命令行执行 <code>code --version</code>，第二行即 commit 哈希。</li></ul> <h3 id="_2-在本地下载对应的-server-包" tabindex="-1">2. 在本地下载对应的 server 包 <a class="header-anchor" href="#_2-在本地下载对应的-server-包" aria-label="Permalink to &quot;2. 在本地下载对应的 server 包&quot;">​</a></h3> <p>浏览器直接访问以下地址即可触发下载（把 <code>${commit id}</code> 替换为上一步的值）：</p> <div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://update.code.visualstudio.com/commit:${commit id}/server-linux-x64/stable</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>服务器是 arm64 架构时，把 <code>server-linux-x64</code> 换成 <code>server-linux-arm64</code>。</p> <h3 id="_3-传到服务器并解压" tabindex="-1">3. 传到服务器并解压 <a class="header-anchor" href="#_3-传到服务器并解压" aria-label="Permalink to &quot;3. 传到服务器并解压&quot;">​</a></h3> <div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vscode-server-linux-x64.tar.gz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user@server:~/</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ssh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> user@server</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.vscode-server/bin/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">${commit id}</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -zxf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/vscode-server-linux-x64.tar.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --strip-components=1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.vscode-server/bin/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">${commit id}</span></span></code></pre> <div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>完成后本地重新连接，VS Code 检测到对应 commit 的 server 已就位就不再下载。</p> <h2 id="两个关键细节" tabindex="-1">两个关键细节 <a class="header-anchor" href="#两个关键细节" aria-label="Permalink to &quot;两个关键细节&quot;">​</a></h2> <h3 id="解压必须去掉顶层目录" tabindex="-1">解压必须去掉顶层目录 <a class="header-anchor" href="#解压必须去掉顶层目录" aria-label="Permalink to &quot;解压必须去掉顶层目录&quot;">​</a></h3> <p>tar 包解压出来是 <code>vscode-server-linux-x64/</code> 目录，而 VS Code 期望的布局是 <code>~/.vscode-server/bin/${commit id}/bin/</code> 下直接有可执行文件。如果不加 <code>--strip-components=1</code>，解压结果会多一层目录，server 启动脚本位置不对，连接照样失败。这是多数教程没讲清、实操最容易翻车的一步。</p> <h3 id="本地-vs-code-升级后要重新做" tabindex="-1">本地 VS Code 升级后要重新做 <a class="header-anchor" href="#本地-vs-code-升级后要重新做" aria-label="Permalink to &quot;本地 VS Code 升级后要重新做&quot;">​</a></h3> <p>commit id 随版本变化，本地 VS Code 一升级，服务器上旧 commit 的 server 就不再匹配，需要按新 commit id 重新下载放置。另外，VS Code 1.86 之后 server 安装流程引入了 CLI 组件与新的目录结构（<code>~/.vscode-server/cli/servers/Stable-{commit}</code>），若按上述步骤放好仍连不上，先检查服务器上是否存在这个新路径体系，再对照官方文档处理。</p> <h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2> <p>卡在下载服务器，本质是服务器侧出网受阻。手动安装的关键三点：commit id 要与本地版本精确匹配（Help → About 获取）、下载 URL 按架构选对变体、解压加 <code>--strip-components=1</code> 保证目录层级正确。步骤依据见 <a href="https://stackoverflow.com/questions/77068802/how-do-i-install-vscode-server-offline-on-a-server-for-vs-code-version-1-82-0-or" target="_blank" rel="noreferrer">Stack Overflow 的离线安装讨论</a> 与 <a href="https://learn.microsoft.com/en-us/answers/questions/6022101/" target="_blank" rel="noreferrer">Microsoft Learn 的手动安装步骤</a>。若服务器只是网络慢而非完全不通，也可以只给服务器配置代理后让 VS Code 自动完成下载。</p>',37)])])}const k=s(t,[["render",r]]);export{m as __pageData,k as default};
